const express = require('express');
const { RateLimiterRedis } = require('rate-limiter-flexible');
const Redis = require('ioredis');

const app = express();
app.use(express.json());
const redisClient = new Redis(process.env.REDIS_URL);

const rateLimiter = new RateLimiterRedis({
  storeClient: redisClient,
  keyPrefix: 'rl_quotes',
  points: 100,
  duration: 60
});

app.post('/api/v1/market-data/realtime-quotes', async (req, res) => {
  if (!req.user || !req.user.tenantId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Key consumption strictly by the verified session tenantId
  const authenticatedTenant = req.user.tenantId;

  try {
    await rateLimiter.consume(authenticatedTenant, 10);
  } catch (rejRes) {
    return res.status(429).json({
      error: 'Rate limit exceeded for your tenant',
      retryAfterSeconds: Math.round(rejRes.msBeforeNext / 1000)
    });
  }

  const { symbols } = req.body;
  res.json({ tenant: authenticatedTenant, symbols, status: 'STREAMING_QUOTES' });
});

app.listen(9001);
